mapper.select:
SELECT topic.topic_id, topic.group_session_id, topic.root_message_id, topic.last_message_id, topic.last_activity_at, topic.create_time FROM byai_group_chat_topic topic WHERE topic.group_session_id = #{sessionId} AND EXISTS ( SELECT 1 FROM byai_message message WHERE message.session_id = topic.group_session_id AND message.topic_id = topic.topic_id AND message.recalled_at IS NULL )
AND (topic.last_activity_at, topic.last_message_id, topic.topic_id) < (#{beforeTime}, #{beforeMessageId}, #{beforeTopicId})
ORDER BY topic.last_activity_at DESC, topic.last_message_id DESC, topic.topic_id DESC LIMIT #{limit}
